#include <iostream>

// Function accepts an integer pointer (*)
void modifyValue(int* ptr) {
    if (ptr != nullptr) {      // Good practice: check for null pointers
        *ptr = 99;             // Dereference (*) to change the original variable's value
    }
}

int main() {
    int num = 10;

    // Pass the address (&) of num to the function
    modifyValue(&num);

    std::cout << num; // Outputs 99, since the original variable was changed
    return 0;
}

#include <iostream>

void modifyValue(int &num) {
    num = 20; // Modifies the original variable
}

int main() {
    int x = 10;
    modifyValue(x);
    std::cout << x; // Outputs 20
    return 0;
}

